import json
n=30
G=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Original tile outlines and interiors.
for i,r0 in enumerate(starts):
 for j,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n and (dr in (0,4) or dc in (0,4)): G[r][c]=4
  if i<4 and j<4:
   for dr in range(1,4):
    for dc in range(1,4): G[r0+dr][c0+dc]=colors[i][j]
# Link the two non-dominant colors between repeated tile markers, across blank separators.
for i in range(4):
 for color in (3,8):
  js=[j for j in range(4) if colors[i][j]==color]
  if len(js)>1:
   for a in range(min(js),max(js)):
    for c in range(starts[a]+5, starts[a+1]):
     for dr in range(1,4):
      r=starts[i]+dr
      if G[r][c]==0: G[r][c]=color
for j in range(4):
 for color in (3,8):
  is_=[i for i in range(4) if colors[i][j]==color]
  if len(is_)>1:
   for a in range(min(is_),max(is_)):
    for r in range(starts[a]+5, starts[a+1]):
     for dc in range(1,4):
      c=starts[j]+dc
      if G[r][c]==0: G[r][c]=color
print(json.dumps(G,separators=(',',':')))
